// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React from "react";
import {
  useCurrentFrame,
  useVideoConfig,
  AbsoluteFill,
  interpolate,
  spring,
  Easing,
} from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadInter = makeLoadFont('Inter');

const { fontFamily: interFamily } = loadInter();



export type ERPFlowAnimationProps = Record<string, any>;

// Utility for adapting text/border colors based on background
const hexToRgb = (hex: string) => {
  const shorthandRegex = /^#?([a-f\d])([a-f\d])([a-f\d])$/i;
  const fullHex = hex.replace(shorthandRegex, (m, r, g, b) => r + r + g + g + b + b);
  const result = /^#?([a-f\d]{2})([a-f\d]{2})([a-f\d]{2})$/i.exec(fullHex);
  return result
    ? { r: parseInt(result[1], 16), g: parseInt(result[2], 16), b: parseInt(result[3], 16) }
    : null;
};

const getLuminance = (hex: string) => {
  const rgb = hexToRgb(hex);
  if (!rgb) return 1;
  const a = [rgb.r, rgb.g, rgb.b].map((v) => {
    v /= 255;
    return v <= 0.03928 ? v / 12.92 : Math.pow((v + 0.055) / 1.055, 2.4);
  });
  return a[0] * 0.2126 + a[1] * 0.7152 + a[2] * 0.0722;
};

const ERPFlowAnimation: React.FC<ERPFlowAnimationProps> = ({
  backgroundColor = "#F8FAFC",
  transparentBackground = false,
  durationInSeconds = 5,
  accentColor = "#3B82F6",
  inputLabel = "Notes",
  centerLabel = "Processing",
  rightLabel = "Tato (ERP AI)",
  rightSubtext = "Turns input into execution.",
  inputLines = [
    "Client meeting notes review",
    "Due next Friday by 5pm",
    "Assign follow-ups to Sarah",
  ],
  outputCards = [
    { type: "Task", title: "Review Meeting Notes", subtitle: "Client Alignment" },
    { type: "Deadline", title: "Next Friday, 5:00 PM", subtitle: "Strict" },
    { type: "Owner", title: "Sarah Jenkins", subtitle: "Operations Team" },
  ],
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  const isDark = getLuminance(backgroundColor) < 0.5;
  const textColor = isDark ? "#F8FAFC" : "#0F172A";
  const secondaryTextColor = isDark ? "#94A3B8" : "#64748B";
  const panelBg = isDark ? "rgba(30, 41, 59, 0.7)" : "#FFFFFF";
  const panelBorder = isDark ? "rgba(255, 255, 255, 0.1)" : "rgba(0, 0, 0, 0.05)";
  const bgColor = transparentBackground ? "transparent" : backgroundColor;

  // Layout Metrics
  const panelWidth = 460;
  const panelHeight = 700;
  const panelY = (height - panelHeight) / 2;
  const leftPanelX = 120;
  const rightPanelX = width - panelWidth - 120;
  const centerY = height / 2;

  // Timing Setup
  const totalFrames = durationInSeconds * fps;
  const itemsCount = Math.max(inputLines.length, outputCards.length);
  const staggerFrames = Math.floor((totalFrames * 0.1) / Math.max(itemsCount, 1));

  const t0_base = Math.floor(totalFrames * 0.08); // Input items start appearing
  const t1_base = Math.floor(totalFrames * 0.3); // Flow movement starts
  const t2_base = Math.floor(totalFrames * 0.65); // Snap to output cards

  // Initial Panel Appearance Springs
  const leftPanelScale = spring({ fps, frame: frame - 5, config: { damping: 14 } });
  const rightPanelScale = spring({ fps, frame: frame - 15, config: { damping: 14 } });
  const pipelineOpacity = interpolate(frame, [20, 40], [0, 1], { extrapolateLeft: "clamp", extrapolateRight: "clamp" });

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, fontFamily: interFamily }}>
      
      {/* BACKGROUND PIPELINE */}
      <svg
        style={{
          position: "absolute",
          top: 0,
          left: 0,
          width: "100%",
          height: "100%",
          opacity: pipelineOpacity,
          pointerEvents: "none",
          transition: "none",
        }}
      >
        <line
          x1={leftPanelX + panelWidth}
          y1={centerY}
          x2={rightPanelX}
          y2={centerY}
          stroke={accentColor}
          strokeWidth={3}
          strokeDasharray="8 8"
          strokeLinecap="round"
          strokeDashoffset={-frame * 1.5}
          opacity={0.4}
          style={{ transition: "none" }}
        />
      </svg>

      {/* CENTER LABEL */}
      <div
        style={{
          position: "absolute",
          left: "50%",
          top: centerY - 40,
          transform: "translateX(-50%)",
          opacity: pipelineOpacity,
          color: accentColor,
          fontWeight: 600,
          fontSize: 14,
          letterSpacing: "0.1em",
          textTransform: "uppercase",
          background: isDark ? "rgba(15, 23, 42, 0.8)" : "rgba(255, 255, 255, 0.8)",
          padding: "4px 12px",
          borderRadius: 20,
          transition: "none",
        }}
      >
        {centerLabel}
      </div>

      {/* LEFT PANEL: NOTES */}
      <div
        style={{
          position: "absolute",
          left: leftPanelX,
          top: panelY,
          width: panelWidth,
          height: panelHeight,
          backgroundColor: panelBg,
          border: `1px solid ${panelBorder}`,
          borderRadius: 24,
          boxShadow: "0 25px 50px -12px rgba(0, 0, 0, 0.05)",
          padding: 40,
          transform: `scale(${leftPanelScale})`,
          transformOrigin: "center",
          display: "flex",
          flexDirection: "column",
          transition: "none",
        }}
      >
        <h2 style={{ margin: 0, fontSize: 24, fontWeight: 600, color: textColor }}>
          {inputLabel}
        </h2>
        <div
          style={{
            marginTop: 16,
            marginBottom: 32,
            height: 2,
            width: 40,
            backgroundColor: accentColor,
            borderRadius: 2,
          }}
        />
        {/* Input items are rendered globally to allow floating, not constrained here */}
      </div>

      {/* RIGHT PANEL: OUTPUT */}
      <div
        style={{
          position: "absolute",
          left: rightPanelX,
          top: panelY,
          width: panelWidth,
          height: panelHeight,
          backgroundColor: panelBg,
          border: `1px solid ${panelBorder}`,
          borderRadius: 24,
          boxShadow: "0 25px 50px -12px rgba(0, 0, 0, 0.05)",
          padding: 40,
          transform: `scale(${rightPanelScale})`,
          transformOrigin: "center",
          display: "flex",
          flexDirection: "column",
          transition: "none",
        }}
      >
        <h2 style={{ margin: 0, fontSize: 24, fontWeight: 700, color: textColor }}>
          {rightLabel}
        </h2>
        <p style={{ margin: "4px 0 0 0", fontSize: 15, color: secondaryTextColor }}>
          {rightSubtext}
        </p>
        <div
          style={{
            marginTop: 16,
            marginBottom: 24,
            height: 2,
            width: 40,
            backgroundColor: accentColor,
            borderRadius: 2,
          }}
        />

        {/* OUTPUT CARDS */}
        <div style={{ position: "relative", flex: 1 }}>
          {outputCards.map((card, i) => {
            const safeT2 = Math.max(t2_base + i * staggerFrames, 10);
            const cardSpring = spring({ fps, frame: frame - safeT2, config: { damping: 12 } });
            const cardOpacity = interpolate(frame, [safeT2, safeT2 + 5], [0, 1], {
              extrapolateLeft: "clamp", extrapolateRight: "clamp",
            });

            return (
              <div
                key={`card-${i}`}
                style={{
                  position: "absolute",
                  top: i * 140,
                  left: 0,
                  width: "100%",
                  padding: 20,
                  borderRadius: 16,
                  backgroundColor: isDark ? "rgba(0,0,0,0.2)" : "#F8FAFC",
                  border: `1px solid ${panelBorder}`,
                  transform: `scale(${cardSpring}) translateY(${interpolate(
                    frame,
                    [safeT2, safeT2 + 15],
                    [20, 0],
                    { extrapolateLeft: "clamp", extrapolateRight: "clamp", easing: Easing.out(Easing.quad) }
                  )}px)`,
                  opacity: cardOpacity,
                  display: "flex",
                  flexDirection: "column",
                  gap: 12,
                  transition: "none",
                }}
              >
                <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center" }}>
                  <span
                    style={{
                      fontSize: 12,
                      fontWeight: 700,
                      color: accentColor,
                      backgroundColor: `${accentColor}20`,
                      padding: "4px 10px",
                      borderRadius: 8,
                      textTransform: "uppercase",
                      letterSpacing: "0.05em",
                    }}
                  >
                    {card.type}
                  </span>
                  <span style={{ fontSize: 13, color: secondaryTextColor, fontWeight: 500 }}>
                    {card.subtitle}
                  </span>
                </div>
                <div style={{ fontSize: 18, fontWeight: 600, color: textColor }}>
                  {card.title}
                </div>
              </div>
            );
          })}
        </div>
      </div>

      {/* FLOWING INPUT ITEMS */}
      {inputLines.map((line, i) => {
        const safeT0 = t0_base + i * staggerFrames;
        const safeT1 = Math.max(safeT0 + 10, t1_base + i * staggerFrames);
        const safeT2 = Math.max(safeT1 + 20, t2_base + i * staggerFrames);

        // Calculate exact absolute screen coordinates
        const startX = leftPanelX + 40;
        const startY = panelY + 120 + i * 70;
        const endX = rightPanelX + 40;
        const endY = panelY + 130 + i * 140; // Approximate center of target card

        // Strictly increasing frame array for interpolation
        const f1 = safeT1;
        const f2 = safeT1 + 10;
        const f3 = Math.max(f2 + 1, safeT2 - 10);
        const f4 = Math.max(f3 + 1, safeT2);

        const x = interpolate(frame, [f1, f4], [startX, endX], {
          extrapolateLeft: "clamp", extrapolateRight: "clamp",
          easing: Easing.inOut(Easing.quad),
        });

        const y = interpolate(frame, [f1, f2, f3, f4], [startY, centerY, centerY, endY], {
          extrapolateLeft: "clamp", extrapolateRight: "clamp",
          easing: Easing.inOut(Easing.quad),
        });

        const scale = interpolate(frame, [f1, f2, f3, f4], [1, 0.6, 0.6, 1], {
          extrapolateLeft: "clamp", extrapolateRight: "clamp",
        });

        const appearOpacity = interpolate(frame, [safeT0, safeT0 + 10], [0, 1], { extrapolateLeft: "clamp", extrapolateRight: "clamp" });
        const disappearOpacity = interpolate(frame, [safeT2 - 5, safeT2], [1, 0], { extrapolateLeft: "clamp", extrapolateRight: "clamp" });
        const finalOpacity = appearOpacity * disappearOpacity;

        const appearSpring = spring({ fps, frame: frame - safeT0, config: { damping: 14 } });
        const combinedScale = frame < f1 ? appearSpring : scale;

        return (
          <div
            key={`input-${i}`}
            style={{
              position: "absolute",
              left: 0,
              top: 0,
              transform: `translate(${x}px, ${y}px) scale(${combinedScale})`,
              opacity: finalOpacity,
              transformOrigin: "left center",
              fontSize: 16,
              fontWeight: 500,
              color: textColor,
              padding: "12px 16px",
              borderLeft: `4px solid ${accentColor}`,
              backgroundColor: isDark ? "rgba(255,255,255,0.03)" : "#F1F5F9",
              borderRadius: "0 8px 8px 0",
              width: panelWidth - 80,
              whiteSpace: "nowrap",
              overflow: "hidden",
              textOverflow: "ellipsis",
              boxShadow: frame >= f1 ? "0 10px 25px -5px rgba(0,0,0,0.1)" : "none",
              transition: "none",
            }}
          >
            {line}
          </div>
        );
      })}
    </AbsoluteFill>
  );
};

export default ERPFlowAnimation;